import Combine
import Foundation
import Swinject

enum SigningRecipientResolver {

	static func currentUserSigner(
		from recipients: [Envelope.Recipients],
		agentEmail: String?
	) -> Envelope.Recipients? {
		let activeRecipients = activeSigningRecipients(from: recipients)

		if let normalizedAgentEmail = normalized(agentEmail), !normalizedAgentEmail.isEmpty {
			let emailMatches = activeRecipients.filter {
				normalized($0.email) == normalizedAgentEmail
			}
			if emailMatches.count == 1 {
				return emailMatches[0]
			}
			if emailMatches.count > 1 {
				return nil
			}
		}

		let titledMatches = activeRecipients.filter {
			$0.title?.caseInsensitiveCompare("Me") == .orderedSame
		}
		return titledMatches.count == 1 ? titledMatches[0] : nil
	}

	static func inPersonSigners(
		from recipients: [Envelope.Recipients],
		agentEmail: String?
	) -> [Envelope.Recipients] {
		let normalizedAgentEmail = normalized(agentEmail)
		return activeSigningRecipients(from: recipients).filter {
			$0.title?.caseInsensitiveCompare("Me") != .orderedSame
				&& normalized($0.email) != normalizedAgentEmail
		}
	}

	private static func activeSigningRecipients(
		from recipients: [Envelope.Recipients]
	) -> [Envelope.Recipients] {
		let candidates = recipients.filter {
			guard let status = $0.status,
				  $0.isActive == true,
				  $0.group != nil else {
				return false
			}

			return $0.role.caseInsensitiveCompare("Signer") == .orderedSame
				&& status.caseInsensitiveCompare("InProgress") == .orderedSame
		}

		guard let activeGroupOrder = candidates.compactMap(\.group?.order).min() else {
			return []
		}

		return candidates.filter { $0.group?.order == activeGroupOrder }
	}

	private static func normalized(_ value: String?) -> String? {
		value?
			.trimmingCharacters(in: .whitespacesAndNewlines)
			.lowercased()
	}
}

