class FeatureManager {
	static let shared = FeatureManager()
	private let config = RemoteConfig.remoteConfig()

	func isAutoSplitAssignEnabled() -> Bool {
		return config.configValue(forKey: RemoteConfigKey.splitAssign).boolValue
	}

	func isSignNowEnabled() -> Bool {
		return config.configValue(forKey: RemoteConfigKey.signNow).boolValue
	}

	func isSignInPersonEnabled() -> Bool {
		return config.configValue(forKey: RemoteConfigKey.signInPerson).boolValue
	}
}

